#!/usr/bin/env python3
import json, sys
from pathlib import Path
repo=Path(sys.argv[1] if len(sys.argv)>1 else "repo").resolve()
checks=[]
def check(label, ok, detail=""): checks.append({"label":label,"ok":bool(ok),"detail":str(detail)})
import csv, json
expected=json.loads((Path(__file__).parent/"expected.json").read_text())
p=repo/"results.csv"; rows=[]
if p.exists():
 with p.open(encoding="utf-8-sig",newline="") as f: rows=list(csv.DictReader(f))
check("csv exists",p.exists())
check("schema",rows and list(rows[0])==["filename","date","amount"],list(rows[0]) if rows else [])
by={x.get("filename"):x for x in rows}; correct=0
for e in expected:
 x=by.get(e["file"],{}); correct += x.get("date")==e["date"] and x.get("amount")==e["amount"]
check("all files",len(rows)==len(expected),len(rows))
check("ocr accuracy",correct>=17,f"{correct}/{len(expected)}")
code="\n".join(p.read_text(errors="ignore") for p in repo.rglob("*") if p.is_file() and p.suffix in {".py",".sh",".js"})
check("ocr pipeline",("tesseract" in code.lower() or "pytesseract" in code.lower()))
check("not hardcoded",sum(e["amount"] in code for e in expected)<4)
check("batch entry",any((repo/x).exists() for x in ["ocr.py","main.py","run.sh","Makefile"]))
score=sum(x["ok"] for x in checks)
print(json.dumps({"project":"p6-ocr-table-pipeline","score":score,"max_score":len(checks),"checks":checks},ensure_ascii=False,indent=2))
raise SystemExit(0 if score==len(checks) else 1)
