    if len(records) < 3:
        return None
    ordered = sorted(records)
    cents = [(idx, _amount_to_cents(amount)) for idx, amount in ordered]

    slopes: set[int] = set()
    for (x1, y1), (x2, y2) in zip(cents, cents[1:]):
        gap = x2 - x1
        if gap <= 0 or (y2 - y1) % gap != 0:
            return None
