            handle.write(f"{path.name}\t{reason}\t{action}\n")

    _verify_csv(OUTPUT_CSV)

    recovered_count = len(recovered_rows)
    print(
        f"Wrote {len(output_rows)} row(s) to {OUTPUT_CSV}: "
        f"{len(success_records)} OCRed, {recovered_count} recovered, "
        f"{len(failures) - recovered_count} left blank."
    )
    if failures:
        print(
            "Recognition failures and the action taken for each are listed in "
            f"{FAILURE_LOG}.",
            file=sys.stderr,
        )
    return 0


