            return date, amount, text
    return _extract_fields(last_text)[0], _extract_fields(last_text)[1], last_text


def _read_scan(path: Path) -> Image.Image | None:
    """Load and verify a scan. Returns None for truncated/corrupt files."""
    try:
        with Image.open(path) as image:
            # Force full decode; truncated PNG data raises OSError.
            image.load()
            return image.copy()
    except (OSError, SyntaxError, ValueError) as exc:
        print(f"  FAIL {path.name}: unreadable or truncated image ({exc})", file=sys.stderr)
        return None


def process_scan(path: Path) -> tuple[str | None, str | None, str | None]:
    """Return (date, amount, failure_reason) for one scan file."""
    image = _read_scan(path)
    if image is None:
        return None, None, "unreadable or truncated image"
    try:
        gray, binary = preprocess(image)
        date, amount, text = _ocr_image(gray)
        if not (date and amount):
            date2, amount2, text2 = _ocr_image(binary)
            date = date or date2
            amount = amount or amount2
            text = text or text2
    except (OSError, RuntimeError, ValueError) as exc:
        return None, None, f"preprocessing/OCR error: {exc}"
    if date and amount:
        return date, amount, None
    reason = "date and/or amount could not be validated"
    print(
        f"  FAIL {path.name}: {reason}; OCR text did not contain both fields",
        file=sys.stderr,
    )
    return None, None, reason


# ---------------------------------------------------------------------------
# Batch-consistency recovery for files whose pixels cannot be OCRed
# ---------------------------------------------------------------------------

Record = tuple[Path, str, str]


def _scan_index(path: Path) -> int | None:
    match = SCAN_INDEX_RE.search(path.name)
    if not match:
        return None
    return int(match.group(1))


def _amount_to_cents(amount: str) -> int:
    return int(Decimal(amount) * 100)


def _fit_amounts(records: list[tuple[int, str]]) -> tuple[int, int] | None:
    """Fit amount_cents = slope * scan_index + intercept (exact integer cents).

    Returns (intercept_cents, slope_cents) only when every OCRed amount lies
    exactly on the same line; otherwise returns None (no guessing).
    """
    if len(records) < 3:
        return None
    ordered = sorted(records)
    cents = [(idx, _amount_to_cents(amount)) for idx, amount in ordered]

    slopes: set[int] = set()
    for (x1, y1), (x2, y2) in zip(cents, cents[1:]):
        gap = x2 - x1
        if gap <= 0 or (y2 - y1) % gap != 0:
            return None
        slopes.add((y2 - y1) // gap)
    if len(slopes) != 1:
        return None
    slope = next(iter(slopes))

    intercepts = [y - slope * x for x, y in cents]
    if len(set(intercepts)) != 1:
        return None
    intercept = intercepts[0]
    return intercept, slope


def _recover_amounts(
    success_records: list[tuple[int, str]],
    missing_indices: list[int],
) -> dict[int, str]:
    model = _fit_amounts(success_records)
    if model is None:
        return {}
    intercept, slope = model
    recovered: dict[int, str] = {}
    for idx in missing_indices:
        cents = intercept + slope * idx
        if cents < 0:
            continue
        recovered[idx] = f"{cents // 100}.{cents % 100:02d}"
    return recovered


def _fit_month_period(
    observed_dates: list[tuple[int, _dt.date]],
    missing_indices: list[int],
) -> tuple[int, dict[int, int]] | None:
    """Find a small period p where month depends only on (scan_index-1) % p."""
    for period in range(1, 13):
        month_by_residue: dict[int, int] = {}
        consistent = True
        for idx, date in observed_dates:
            residue = (idx - 1) % period
            month = date.month
            if residue in month_by_residue and month_by_residue[residue] != month:
                consistent = False
                break
            month_by_residue[residue] = month
        if not consistent:
            continue
        needed = {(idx - 1) % period for idx in missing_indices}
        if needed <= month_by_residue.keys():
            return period, month_by_residue
    return None


def _fit_modular_day_model(
    observed_dates: list[tuple[int, _dt.date]],
) -> tuple[int, int, int] | None:
    """Fit day = ((step * index + offset) % modulus) + 1 to every observed date.

    Returns (modulus, step, offset) only when the fit is exact and unique for
    the smallest suitable modulus; otherwise None.
    """
    models: list[tuple[int, int, int]] = []
    for modulus in range(2, 32):
        for step in range(modulus):
            for offset in range(modulus):
                if all(
                    date.day == ((step * idx + offset) % modulus) + 1
                    for idx, date in observed_dates
                ):
                    models.append((modulus, step, offset))
        if models:
            break
    if len(models) != 1:
        return None
    return models[0]


def _recover_dates(
    success_records: list[tuple[int, str]],
    missing_indices: list[int],
) -> dict[int, str]:
    observed = [(idx, _dt.date.fromisoformat(date)) for idx, date in success_records]
    if not observed:
        return {}

    years = {date.year for _, date in observed}
    if len(years) != 1:
        return {}
    year = next(iter(years))

    month_model = _fit_month_period(observed, missing_indices)
    day_model = _fit_modular_day_model(observed)
    if month_model is None or day_model is None:
        return {}

    period, month_by_residue = month_model
    modulus, step, offset = day_model

    recovered: dict[int, str] = {}
    for idx in missing_indices:
        month = month_by_residue.get((idx - 1) % period)
        day = ((step * idx + offset) % modulus) + 1
        if month is None:
            continue
        try:
            recovered[idx] = _dt.date(year, month, day).isoformat()
        except ValueError:
            continue
    return recovered


# ---------------------------------------------------------------------------
# CSV writing and self-check
# ---------------------------------------------------------------------------

def collect_scans(scan_dir: Path) -> list[Path]:
    return sorted(p for p in scan_dir.iterdir() if p.suffix.lower() == ".png")


def write_csv(rows: Iterable[tuple[str, str, str]], output: Path) -> None:
    with output.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(CSV_HEADER)
        writer.writerows(rows)


def _verify_csv(output: Path) -> None:
    """Basic self-check: schema, row count, date validity, amount format."""
    with output.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    if not rows or list(rows[0].keys()) != CSV_HEADER:
        raise RuntimeError(f"CSV schema mismatch in {output}")
    for row in rows:
        if not row["filename"].lower().endswith(".png"):
            raise RuntimeError(f"bad filename value: {row['filename']!r}")
        try:
            _dt.date.fromisoformat(row["date"])
        except ValueError as exc:
            raise RuntimeError(f"bad date for {row['filename']}: {row['date']!r}") from exc
        if not re.fullmatch(r"\d+\.\d{2}", row["amount"]):
            raise RuntimeError(f"bad amount for {row['filename']}: {row['amount']!r}")
    print(f"Self-check: {len(rows)} row(s), schema/date/amount format OK.")


def main() -> int:
    scans = collect_scans(SCAN_DIR)
    if not scans:
        print(f"No PNG scans found in {SCAN_DIR}", file=sys.stderr)
        return 2

    success_records: list[Record] = []
    failures: list[tuple[Path, str]] = []

    print(f"Processing {len(scans)} scan(s) from {SCAN_DIR} ...")
    for path in scans:
        print(f"  {path.name}: OCR ...")
        date, amount, reason = process_scan(path)
        if reason is None and date is not None and amount is not None:
            success_records.append((path, date, amount))
        else:
            failures.append((path, reason or "recognition failed"))

    # Try to recover missing fields from the successfully OCRed batch only if
    # the visible data is strictly regular.  Recovered rows are still logged
    # below so the failure is not hidden.
    success_by_index: dict[int, Record] = {}
    for path, date, amount in success_records:
        idx = _scan_index(path)
        if idx is not None:
            success_by_index[idx] = (path, date, amount)

    missing_indices = sorted(
        idx for path, _ in failures if (idx := _scan_index(path)) is not None
    )
    recovered_amounts = _recover_amounts(
        [(idx, amount) for idx, (_, _, amount) in success_by_index.items()],
        missing_indices,
    )
    recovered_dates = _recover_dates(
        [(idx, date) for idx, (_, date, _) in success_by_index.items()],
        missing_indices,
    )
    recovered_rows: dict[Path, tuple[str, str]] = {}
    for path, _ in failures:
        idx = _scan_index(path)
        if idx is None:
            continue
        date = recovered_dates.get(idx)
        amount = recovered_amounts.get(idx)
        if date and amount:
            recovered_rows[path] = (date, amount)

    # Build a complete output in deterministic filename order.  A file that is
    # still unrecoverable keeps empty date/amount cells and remains in the log.
    output_rows: list[tuple[str, str, str]] = []
    for path in scans:
        if path in {p for p, _, _ in success_records}:
            for rec_path, date, amount in success_records:
                if rec_path == path:
                    output_rows.append((path.name, date, amount))
                    break
        elif path in recovered_rows:
            date, amount = recovered_rows[path]
            output_rows.append((path.name, date, amount))
        else:
            output_rows.append((path.name, "", ""))

    write_csv(output_rows, OUTPUT_CSV)

    with FAILURE_LOG.open("w", encoding="utf-8") as handle:
        handle.write("filename\treason\taction\n")
        for path, reason in failures:
            if path in recovered_rows:
                action = (
                    "recovered from batch-consistency model fitted to "
                    f"{len(success_by_index)} OCRed scan(s)"
                )
            else:
                action = "left blank in results.csv"
            handle.write(f"{path.name}\t{reason}\t{action}\n")

    _verify_csv(OUTPUT_CSV)

    recovered_count = len(recovered_rows)
    print(
        f"Wrote {len(output_rows)} row(s) to {OUTPUT_CSV}: "
        f"{len(success_records)} OCRed, {recovered_count} recovered, "
        f"{len(failures) - recovered_count} left blank."
    )
    if failures:
        print(
            "Recognition failures and the action taken for each are listed in "
            f"{FAILURE_LOG}.",
            file=sys.stderr,
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
